public sealed class Suit : IEquatable<Suit> {
    public static readonly Suit Clubs = new("clubs");
    public static readonly Suit Diamonds = new("diamonds");

    private Suit(string key) => Key = key;
    public string Key { get; }

    public bool Equals(Suit? other) => other is not null && Key == other.Key;
    public override bool Equals(object? o) => Equals(o as Suit);
    public override int GetHashCode() => Key.GetHashCode();
}

public enum Suit { Clubs, Diamonds, Hearts, Spades }

public static class SuitExtensions {
    public static string Key(this Suit s) => s switch {
        Suit.Clubs => "clubs", Suit.Diamonds => "diamonds",
        Suit.Hearts => "hearts", Suit.Spades => "spades",
        _ => throw new ArgumentOutOfRangeException(nameof(s))  // (Suit)99 is legal
    };
}

